const revokeSessionsByPrincipal = `-- name: RevokeSessionsByPrincipal :many
UPDATE authn_sessions SET revoked_at = ?1, revoke_reason = ?2
WHERE realm_id = ?3 AND principal_type = ?4 AND principal_id = ?5
    AND id <> ?6 AND (revoked_at IS NULL OR revoked_at > ?1)
RETURNING id
`

type RevokeSessionsByPrincipalParams struct {
	At            sql.NullString
	Reason        string
	RealmID       string
	PrincipalType string
	PrincipalID   string
	ExceptID      string
}

func (q *Queries) RevokeSessionsByPrincipal(ctx context.Context, arg RevokeSessionsByPrincipalParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, revokeSessionsByPrincipal,
		arg.At,
		arg.Reason,
		arg.RealmID,
		arg.PrincipalType,
		arg.PrincipalID,
		arg.ExceptID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

